"""Publish native gripper component recordings with exact URDF/STL poses."""
import hashlib
import json
from pathlib import Path
import shutil
import xml.etree.ElementTree as ET
import numpy as np
from .robot import Robot


def export_clamp(output,web_directory,frames=161):
    out=Path(output);web=Path(web_directory);report=json.loads((out/'report.json').read_text())
    if not report['passed']:raise ValueError('Native gripper component verification must pass before publication')
    a=np.load(out/'recording.npz');control=json.loads((out/'control.json').read_text());idx=np.unique(np.linspace(0,len(a['time'])-1,frames).round().astype(int));robot=Robot(out/'model/robot.urdf');meta=json.loads((out/'model/model.json').read_text());revision=meta['source']['revision'];base=f'https://raw.githubusercontent.com/google-deepmind/mujoco_menagerie/{revision}/robotiq_2f85';directory=web/'models/robotiq_2f85';directory.mkdir(parents=True,exist_ok=True);shutil.copyfile(robot.path,directory/'robot.urdf');shutil.copyfile(out/'model/LICENSE',directory/'LICENSE.upstream');urls=[v['url'] for k,v in meta['source']['files'].items() if k.endswith('.stl')];manifest=dict(id='robotiq_2f85',urdf='robot.urdf',packages={'robotiq_2f85':base},source_repository='https://github.com/google-deepmind/mujoco_menagerie',commit=revision,source_path='robotiq_2f85/2f85.xml',source_file_sha256=meta['source']['files']['2f85.xml']['sha256'],urdf_sha256=hashlib.sha256(robot.path.read_bytes()).hexdigest(),license='BSD-2-Clause',license_file='LICENSE.upstream',assets=urls,description='Exact tree frames/inertias derived from the native closed-loop gripper; measured native joint positions animate all linkage bodies.')
    (directory/'model.json').write_text(json.dumps(manifest,indent=2)+'\n')
    root=ET.Element('robot',name='free_calibration_block');link=ET.SubElement(root,'link',name='block');vis=ET.SubElement(link,'visual');ET.SubElement(ET.SubElement(vis,'geometry'),'box',size=' '.join(map(str,report['fixture']['size'])));mat=ET.SubElement(vis,'material',name='block');ET.SubElement(mat,'color',rgba='.66 .43 .22 1');collision=ET.SubElement(link,'collision');ET.SubElement(ET.SubElement(collision,'geometry'),'box',size=' '.join(map(str,report['fixture']['size'])));boxdir=web/'models/robotiq_calibration_block';boxdir.mkdir(parents=True,exist_ok=True);ET.indent(root);(boxdir/'robot.urdf').write_bytes(ET.tostring(root,encoding='utf-8',xml_declaration=True));(boxdir/'LICENSE.authored').write_text((Path(__file__).parent/'scenarios/panel_fixture/LICENSE.authored').read_text());(boxdir/'model.json').write_text(json.dumps(dict(id='robotiq_calibration_block',urdf='robot.urdf',packages={},source='authored free calibration block',license='MIT',license_file='LICENSE.authored',urdf_sha256=hashlib.sha256((boxdir/'robot.urdf').read_bytes()).hexdigest()),indent=2)+'\n')
    links=list(robot.tree.links);positions=[[robot.fk(a['q'][k],n)[:3,3].tolist() for n in links]+[a['object_pose'][k,:3].tolist()] for k in idx];forces=np.array([r['jaw_force_N'] for r in control]);motor=np.array([r['motor_force_Nm'] for r in control]);torque=np.zeros((len(idx),robot.n))
    for j,n in enumerate(robot.joint_names):
        if n.endswith('driver_joint'):torque[:,j]=motor[idx]*.5
    ratio=np.max(np.divide(abs(torque),robot.effort,where=robot.effort>0,out=np.zeros_like(torque)),axis=1);poses=a['object_pose'][idx];q=np.c_[a['q'][idx],poses];data=dict(id='robotiq_2f85',title='Robotiq 2F-85 · 양 jaw 40 N · native mechanism',scenario='robotiq_clamp',engine='mujoco_contact_recording',multi_arm=False,dof=robot.n,nq=q.shape[1],nv=robot.n+6,floating_base=False,frame='native four-bar gripper',joint_names=robot.joint_names,instances=[dict(id='gripper',role='contact_arm',manifest='./models/robotiq_2f85/model.json',joint_names=robot.joint_names,dof=robot.n,floating_base=False,q_indices=list(range(robot.n)),base_pose=dict(position=[0,0,0],quaternion_xyzw=[0,0,0,1])),dict(id='block',role='free_furniture',manifest='./models/robotiq_calibration_block/model.json',joint_names=[],dof=0,floating_base=True,q_indices=list(range(robot.n,robot.n+7)))],objects=[dict(id='calibration_block',index=len(links),poses=poses.tolist(),boxes=[dict(size=report['fixture']['size'],position=[0,0,0],quaternion_xyzw=[0,0,0,1])])],times=a['time'][idx].tolist(),q=q.tolist(),positions=positions,link_names=links+['calibration_block'],edges=[[links.index(j.parent),links.index(j.child)] for j in robot.tree.joints],torques=torque.tolist(),torque_ratio=ratio.tolist(),errors=[None]*len(idx),chart_values=forces[idx].max(axis=1).tolist(),chart_label='MEASURED MAXIMUM JAW NORMAL FORCE',chart_unit='N',keyframes=[dict(id='given_grasp',time=0.,object_pose=a['object_pose'][0].tolist()),dict(id='steady_force',time=3.,object_pose=a['object_pose'][round(3/report['settings']['timestep_s'])].tolist())],events=[],tool_states={'both_jaws_loaded':(forces[idx].min(axis=1)>1).tolist()},environment=[],summary=dict(duration=float(a['time'][-1]),physics_dt=report['settings']['timestep_s'],full_geometry_checked=False),report={**report,'algorithm_validation_passed':False},description='Gripper component verification, separate from the multi-arm paper task. Original Robotiq mesh, native four-bar constraints and finite 5 Nm actuator; a free block held by two measured 40 N jaw reactions. Virtual PMI force admittance drives the native position servo. No object weld or pose playback drives the physics.')
    data.update(viewer_min_extent=.16,display=dict(description='Robotiq 2F-85의 실제 링크·mesh · 내부 기구 제약과 유한 구동기 · 자유 블록을 양 jaw 약 40 N으로 파지한 요소 시험입니다.',scene_label='ROBOTIQ 2F-85 · NATIVE MECHANISM / JAW FORCE TEST',geometry='원본 Robotiq STL과 URDF · 측정된 8개 관절과 자유 블록의 자세를 재생합니다.',chart_note='native 접촉에서 측정한 jaw별 법선력 중 큰 값 · 목표 40 N · 설정 상한 60 N / jaw'))
    (web/'data').mkdir(parents=True,exist_ok=True);(web/'data/robotiq_2f85.json').write_text(json.dumps(data,separators=(',',':'),allow_nan=False));catalog=json.loads((web/'data/index.json').read_text());catalog['models']=[{k:data[k] for k in ['id','title','engine','dof','floating_base']}]+[v for v in catalog['models'] if v['id']!=data['id']];(web/'data/index.json').write_text(json.dumps(catalog,indent=2)+'\n');return data
